"""Standalone asset specimens: actual runtime files, licensed type, and labeled AI direction.
No phone or app-screen mockups. Optional browser screenshots are a separate step.
"""
from pathlib import Path
import json,shutil,html
from build_punk_worlds import COLLECTION,ROOT
from render_illustrated_gallery import CSS as BASE_CSS
CORE=['nav_home','nav_search','nav_explore','nav_library','settings','heart','download','shuffle','repeat','queue','lyrics','headphones','volume_up','add','account','close']
def img(a,p,k,n=48):return f'<img width="{n}" height="{n}" src="{p}{a[k]}" alt="{k.replace("_"," ")}">'
def style(m,prefix):
 a=m['assets'];p=m['palette'];v=':root{'+''.join('--'+{'background':'bg','accentContainer':'container'}.get(k,k)+':'+val+';' for k,val in p.items())+'}'
 return v+f'@font-face{{font-family:Heading;src:url({prefix}{a["headingFont"]})}}@font-face{{font-family:Body;src:url({prefix}{a["bodyFont"]})}}'
CSS='''*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Body,sans-serif}main{max-width:1450px;margin:auto;padding:42px}h1,h2,.display{font-family:Heading;font-weight:400;color:var(--accent)}h1{font-size:70px;line-height:1.25;margin:12px 0 18px}h2{font-size:30px;margin:5px 0 24px}p{line-height:1.65;color:var(--muted);font-size:13px}small,.eyebrow{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:var(--secondary)}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px dashed var(--outline);gap:20px;padding-bottom:18px}header img{width:100px;height:100px}.panel{padding:26px;background:var(--surface);border:1px solid var(--outline);border-radius:22px;margin-top:24px}.topgrid{display:grid;grid-template-columns:1.1fr 1fr;gap:24px}.buttons{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;text-align:center}.buttons img{width:98px;height:98px;max-width:100%;object-fit:contain}.buttons small{display:block;font-size:9px;letter-spacing:1px}.buttons figure{margin:0}.icons{display:grid;grid-template-columns:repeat(4,1fr);gap:20px 12px;text-align:center}.icons img{display:block;margin:0 auto 6px}.icons small{display:block;font-size:9px;letter-spacing:.4px}.rows{display:flex;justify-content:space-between;gap:20px;align-items:center}.rows>div{flex:1}.track{height:11px;width:100%;display:block}.time{display:flex;justify-content:space-between;font-size:10px;color:var(--muted);margin:8px 0 25px}.switch{display:inline-flex;width:75px;height:34px;border-radius:22px;background:var(--accent);padding:5px;justify-content:flex-end;border:1px solid var(--outline);vertical-align:middle;margin:10px}.switch.off{justify-content:flex-start;background:var(--raised)}.switch img{width:24px;height:24px;background:var(--surface);border-radius:50%;padding:4px}.display{font-size:52px;line-height:1.3;margin:18px 0;color:var(--secondary)}.bodytype{font-size:20px;line-height:1.7;color:var(--text);letter-spacing:1px}.palette{display:flex;gap:12px;flex-wrap:wrap;margin-top:24px}.swatch{flex:1;min-width:85px;border-bottom:12px solid var(--accent);background:var(--surface);padding:12px;border-radius:10px;font-size:10px}.motion{display:flex;align-items:center;justify-content:space-around;gap:12px}.frame{text-align:center;border:1px dashed var(--outline);border-radius:12px;padding:12px;flex:1}.frame img{max-width:90px}.frame small{display:block;font-size:9px;letter-spacing:.5px}.arrow{color:var(--accent);font-size:23px}.note{font-size:11px;color:var(--muted);line-height:1.6}a{color:var(--accent)}footer{margin-top:25px;border-top:1px dashed var(--outline);padding-top:18px}.paper{height:55px;background:linear-gradient(135deg,var(--raised),var(--secondary));clip-path:polygon(2% 8%,24% 0,35% 8%,60% 0,85% 10%,99% 0,95% 85%,70% 100%,50% 91%,20% 100%,0 92%);border:1px solid var(--accent);margin:14px}.material{margin-top:25px;height:65px;border-radius:14px;border:1px solid var(--outline);background:linear-gradient(130deg,var(--surface),var(--raised),var(--surface))}.links{display:flex;gap:25px;flex-wrap:wrap}button{font:inherit;cursor:pointer}.interactive{background:transparent;border:none;padding:0;transition:transform 160ms}.interactive:active{transform:scale(.9)}@media(max-width:800px){main{padding:20px}.topgrid{grid-template-columns:1fr}h1{font-size:45px}.display{font-size:36px}.rows{flex-direction:column;align-items:stretch}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}'''
def track(m):
 p=m['palette'];seek=m['seekStyle'];orn=[]
 for i in range(24):
  x=(i+.4)*12.5;color=p['secondary'] if x<114 else p['text']
  if seek in ['gel','plasma','beads']:orn.append(f'<circle cx="{x}" cy="5.5" r="{3 if i%3==0 or seek=="beads" else 1.7}" fill="{color}" opacity=".55"/>')
  elif seek=='cable':orn.append(f'<path d="M{x} 0l10 11" stroke="{color}" opacity=".6"/>')
  else:orn.append(f'<rect x="{x}" y="4" width="6" height="3" fill="{color}" opacity=".6"/>')
 return f'<svg class="track" viewBox="0 0 300 11" preserveAspectRatio="none"><rect width="300" height="11" rx="5" fill="{p["outline"]}"/><rect width="114" height="11" rx="5" fill="{p["accent"]}"/>{"".join(orn)}<path d="M114 0L116 4L120 5L116 7L114 11L112 7L108 5L112 4Z" fill="{p["text"]}"/></svg>'
def render_page(c,prefix):
 m=json.loads((ROOT/c['id']/'theme.json').read_text());a=m['assets'];p=m['palette'];g=lambda key,n=48:img(a,prefix,key,n)
 buttons=''.join(f'<figure>{g(k,100)}<small>{k.replace("_"," ")}</small></figure>' for k in ['play','pause','previous','next','play_pressed','pause_pressed','previous_pressed','next_pressed'])
 icons=''.join(f'<div>{g(k)}<small>{k.replace("nav_","").replace("_"," ")}</small></div>' for k in CORE)
 frames=''.join(f'<div class="frame">{g(k,85)}<small>{text}</small></div>'+('<span class="arrow">→</span>' if i<3 else '') for i,(k,text) in enumerate([('play','REST'),('play_pressed','PRESS'),('play','RELEASE'),('play','SETTLE')]))
 palette=''.join(f'<div class="swatch" style="border-color:{v}">{k}<br>{v}</div>' for k,v in p.items())
 fonttext=c['tagline'].upper()
 body=f'''<header><div><span class="eyebrow">VEYRA / PUNK WORLDS / BUILD 32</span><h1>{c['name']}</h1><p>{c['description']}</p></div>{g('brandIcon',100)}</header><div class="topgrid"><section class="panel"><h2>01 / Primary controls</h2><div class="buttons">{buttons}</div><p class="note">Actual transparent normal/pressed PNG assets. Input, playback and accessibility stay native.</p></section><section class="panel"><h2>02 / Color glyphs</h2><div class="icons">{icons}</div></section></div><section class="panel"><h2>03 / Tracks & switches</h2><div class="rows"><div>{track(m)}<div class="time"><span>0:58</span><span>3:24</span></div>{track(m)}<p class="note">{c['seek'].title()} seek and volume · native real-fraction decoration. Static browser specimens.</p></div><div><div class="switch">{g('switch_on',24)}</div> ON <div class="switch off">{g('switch_off',24)}</div> OFF<p class="note">Native Material switch behavior; themed palette and thumb glyphs.</p></div></div></section><section class="panel"><h2>04 / Real typography</h2><div class="display">{fonttext}</div><div class="display" style="font-size:34px;color:var(--accent)">Aa Bb Cc 0123456789</div><div class="bodytype">Your favorite songs. A little louder.<br>Aa Bb Cc · 0123456789 · Manrope</div><p class="note">Installed display font: {c['font']} · SIL Open Font License. Actual font specimen above; AI lettering and metallic text effects are not a TTF font.</p></section><div class="topgrid"><section class="panel"><h2>05 / Press study</h2><div class="motion">{frames}</div><p class="note">Normal/pressed bitmap states + finite native scale/release feedback. Gel/sticker profiles use a spring; motion preferences win. No frame-sheet character animation.</p></section><section class="panel"><h2>06 / Panel study</h2><div class="motion"><div class="frame"><div class="paper"></div><small>BEFORE</small></div><span class="arrow">→</span><div class="frame"><div class="paper" style="transform:translateX(8px)"></div><small>MOVE</small></div><span class="arrow">→</span><div class="frame"><div class="paper"></div><small>SETTLE</small></div></div><p class="note">Bounded native reveal profile: {c['material']}. Illustrated peel/shutter/comet effects on the AI concept board are art direction; the app uses scale/slide/fade, not a physical simulation.</p></section></div><div class="palette">{palette}</div><footer><div class="links"><a href="assets.html">Every one of the 123 asset roles →</a><a href="art-direction.png">AI art-direction board →</a></div><p class="note">These are standalone asset specimens, not Android screenshots. Full themes require build 32. Independent asset-pack layering remains a separate planned feature. Existing themes, user font overrides, reduced motion and custom Home-style isolation remain supported. Launcher aliases are unchanged.</p></footer>'''
 page=f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{c["name"]} · actual asset specimens</title><style>{style(m,prefix)}{CSS}</style><main>{body}</main></html>'
 cards=[]
 for k,v in a.items():
  wide=k.endswith('Font') or k in ['header','player','preview']
  sample=f'<div class="{"heading" if k=="headingFont" else "body"}">Loud little world.<br>Aa Bb 012345</div>' if k.endswith('Font') else f'<img class="{"art" if k in ["header","player","preview"] else "brand" if k=="brandIcon" else "glyph"}" src="{prefix}{v}" alt="{k}">'
  cards.append(f'<article class="asset {"wide" if wide else ""}"><div class="sample">{sample}</div><h3>{k.replace("_"," ")}</h3><code>{v}</code></article>')
 sheet=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{c['name']} · all assets</title><style>{style(m,prefix)}{BASE_CSS}h1,h2,.heading{{color:var(--accent)}}.grid{{grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}}.sample{{height:72px}}.asset{{padding:10px}}.asset h3{{font-size:14px;font-family:Body}}.wide .sample{{height:160px}}.heading,.body{{font-size:30px}}h1{{font-size:58px}}</style><main><span class="eyebrow">VEYRA · PUNK WORLDS · EVERY RUNTIME ASSET</span><h1>{c['name']}</h1><p>123 asset roles: 113 normal functional glyphs, four player pressed-state variants, in-app brand, two fonts and three artwork roles sharing one original wallpaper. These are actual runtime files; typeface is {c['font']} + Manrope.</p><div class="grid">{''.join(cards)}</div></main></html>'''
 return page,sheet

def overview(prefix):
 cards=[];fonts=''
 for c in COLLECTION:
  m=json.loads((ROOT/c['id']/'theme.json').read_text());a=m['assets'];p=m['palette'];font='F'+c['id'].replace('-','')
  fonts+=f'@font-face{{font-family:{font};src:url({prefix(c["id"],a["headingFont"])})}}'
  glyphs=''.join(img(a,prefix(c['id'],''),k,38) for k in ['play','pause','nav_home','settings'])
  cards.append(f'<article style="--bg:{p["background"]};--accent:{p["accent"]};--text:{p["text"]};--muted:{p["muted"]};background:{p["surface"]}"><img class="wall" src="{prefix(c["id"],a["header"])}" alt="{c["name"]} wallpaper"><div class="inside"><h2 style="font-family:{font}">{c["name"]}</h2><small>{c["medium"]}</small><p>{c["tagline"]}</p><div class="glyphs">{glyphs}</div><p class="detail">{c["font"]}<br>Full-color icons · 4 pressed states<br>{c["seek"].title()} track · native motion</p></div></article>')
 return f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Punk Worlds · five complete themes</title><style>{fonts}*{{box-sizing:border-box}}body{{margin:0;background:#100e16;color:#fff5de;font-family:sans-serif}}main{{padding:40px;max-width:2000px;margin:auto}}h1{{font-size:65px;line-height:1.1;margin:12px 0 20px}}header small{{color:#d7ff3b;letter-spacing:3px}}header p{{font-size:15px;color:#decfe0;line-height:1.7}}.worlds{{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:18px;margin-top:28px}}article{{border:1px solid #ffffff35;border-radius:22px;overflow:hidden}}.wall{{width:100%;height:365px;object-fit:cover;display:block}}.inside{{padding:18px}}h2{{font-size:35px;font-weight:400;color:var(--accent);line-height:1.25;margin:0 0 15px;min-height:90px}}small{{font-size:10px;text-transform:uppercase;color:var(--accent)}}p{{color:var(--muted);font-size:13px;line-height:1.7}}.glyphs{{display:flex;justify-content:space-between;padding:14px 0}}.detail{{font-size:11px}}footer{{font-size:12px;color:#c6b9cf;line-height:1.7;margin-top:26px}}@media(max-width:950px){{.worlds{{grid-template-columns:repeat(2,1fr)}}h1{{font-size:44px}}main{{padding:20px}}}}</style><main><header><small>VEYRA / PUNK WORLDS / FIVE COMPLETE THEMES</small><h1>Turn the whole world up.</h1><p>Gel candy · industrial metal · jelly stickers · concert zines · holographic chrome<br>Actual wallpapers, fonts and colored glyphs · 123 asset roles each · beta build 32</p></header><section class="worlds">{''.join(cards)}</section><footer>Collection of actual runtime assets, not app screenshots. Full themes require the updated build-32 beta; stable remains unchanged.<br>Separate AI art-direction boards, every-asset sheets, SVG masters, original wallpaper images and font licenses are included in the delivery bundle.</footer></main></html>'''

def render(out):
 out=Path(out);out.mkdir(parents=True,exist_ok=True)
 for c in COLLECTION:
  d=out/c['id'];shutil.copytree(ROOT/c['id'],d/'assets',dirs_exist_ok=True);shutil.copytree(ROOT/'source-icons'/c['id'],d/'vectors',dirs_exist_ok=True)
  shutil.copyfile(ROOT/'previews'/c['id']/'art-direction.png',d/'art-direction.png')
  for suffix in ['.zip','.zip.sha256']:shutil.copyfile(ROOT/'packs'/f'{c["id"]}-v1{suffix}',d/f'{c["id"]}-v1{suffix}')
  for prefix,where in [('assets/',d),('../../'+c['id']+'/',ROOT/'previews'/c['id'])]:
   where.mkdir(parents=True,exist_ok=True);page,sheet=render_page(c,prefix);(where/'index.html').write_text(page);(where/'assets.html').write_text(sheet)
 (out/'index.html').write_text(overview(lambda k,p:k+'/assets/'+p))
 r=ROOT/'previews/punk-worlds';r.mkdir(parents=True,exist_ok=True);(r/'index.html').write_text(overview(lambda k,p:'../../'+k+'/'+p))
 (out/'README.md').write_text('PUNK WORLDS — five full themes for Veyra beta build 32. Open index.html for the overview, then each theme/index.html for real asset specimens and assets.html for all 123 roles. art-direction.png is a separate AI concept board, not an app screenshot or the installed font. On the updated build-32 app, refresh Settings → Appearance → Theme Studio, then download/apply a theme. Individual ZIPs are the pack files used for distribution; the whole delivery bundle is not an APK. source-art/ includes original generated art; vectors/ contains runtime SVG masters; assets/ contains installed glyphs, fonts, wallpaper and provenance. Asset-pack layering is still a separate planned feature.\n')
if __name__=='__main__':
 import sys;render(sys.argv[1])
